def clear(t):
 for old,new in EDITS.items():t=t.replace(old,new)
 return t

def box(s,x,y,w,h,c=N,kind=MSO_SHAPE.RECTANGLE,line=None):
 q=s.shapes.add_shape(kind,Inches(x),Inches(y),Inches(w),Inches(h));q.fill.solid();q.fill.fore_color.rgb=RGBColor.from_string(c);q.line.color.rgb=RGBColor.from_string(line or c);q._element.spPr.append(OxmlElement('a:effectLst'));return q

def txt(s,x,y,w,h,t,sz=19,c=N,b=False,center=False):
 t=clear(t)
 q=s.shapes.add_textbox(Inches(x),Inches(y),Inches(w),Inches(h));f=q.text_frame;f.word_wrap=True;f.margin_left=f.margin_right=Inches(.08);f.margin_top=f.margin_bottom=Inches(.04)
 for i,l in enumerate(t.split('\n')):
  p=f.paragraphs[0] if not i else f.add_paragraph();p.text=l;p.alignment=PP_ALIGN.CENTER if center else PP_ALIGN.RIGHT;p.space_after=Pt(4);p._p.get_or_add_pPr().set('rtl','1')
  for r in p.runs:
   r.font.name='Vazirmatn';r.font.size=Pt(sz);r.font.bold=b;r.font.color.rgb=RGBColor.from_string(c);rp=r._r.get_or_add_rPr();rp.set('lang','fa-IR');a=OxmlElement('a:cs');a.set('typeface','Vazirmatn');rp.append(a)
 return q

def slide(title,sub='',note=''):
 if title.startswith(('۱۰ | برند','۱۱ | برند','۱۲ | ساختار','۱۳ | یوزرفلو','۲۰ | قواعد')):
  number,rest=title.split(' | ',1)
  title=str(int(number)-2).translate(str.maketrans('0123456789','۰۱۲۳۴۵۶۷۸۹'))+' | '+rest
 s=R.slides.add_slide(R.slide_layouts[6]);s.background.fill.solid();s.background.fill.fore_color.rgb=RGBColor.from_string(N)
 txt(s,.65,.35,14.7,.8,title,30,W,True)
 if sub:txt(s,.65,1.16,14.7,.48,sub,14,'DDE7F3')
 txt(s,.65,8.55,13.6,.3,'SpeakFlow | سند فشردهٔ محصول، مخاطب و مدل کسب‌وکار | ۱۰ نوامبر ۲۰۲۶',10,'DDE7F3')
 txt(s,14.45,8.47,.8,.4,str(len(R.slides)),15,Y,center=True)
 s.notes_slide.notes_text_frame.text=note or sub
 return s

def table(title,headers,rows,widths=None,sub='',note='',size=17):
 s=slide(title,sub,note); widths=widths or [14.7/len(headers)]*len(headers);h=min(.96,6.5/(len(rows)+1));top=1.85
 for ri,row in enumerate([headers]+rows):
  x=15.35
  for j,t in enumerate(row):
   w=widths[j];x-=w;box(s,x,top+ri*h,w-.025,h-.025,Y if ri==0 else (W if ri%2 else P));txt(s,x+.06,top+ri*h+.04,w-.15,h-.09,str(t),size if ri else 17,N,ri==0)
 s.notes_slide.notes_text_frame.text += '\n\n'+'\n'.join(' | '.join(r) for r in [headers]+rows)
 return s

def arr(s,x1,y1,x2,y2,color=N):
 q=s.shapes.add_connector(MSO_CONNECTOR.STRAIGHT,Inches(x1),Inches(y1),Inches(x2),Inches(y2));q.line.color.rgb=RGBColor.from_string(color);q.line.width=Pt(1.4);end=OxmlElement('a:tailEnd');end.set('type','triangle');q._element.spPr.get_or_add_ln().append(end)

